package dev.colonyhorizons.surveyor;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
public record GatheringRecord(UUID id,long revision,int colony,UUID owner,BlockPos hut,int worker,UUID workerUuid,UUID discovery,GatheringOffer offer,int remaining,boolean repeat,State state,String status) {
 public enum State {PREPARING,GATHERING,RETURNING,COMPLETE,RECOVERY_REQUIRED}
 public GatheringRecord {Objects.requireNonNull(id);Objects.requireNonNull(owner);Objects.requireNonNull(workerUuid);Objects.requireNonNull(discovery);Objects.requireNonNull(offer);Objects.requireNonNull(state);Objects.requireNonNull(status);hut=Objects.requireNonNull(hut).immutable();if(revision<0||colony<=0||worker<=0||remaining<0||remaining>offer.ticks()||status.length()>256||state==State.GATHERING&&remaining==0||state==State.PREPARING&&remaining!=offer.ticks()||!GatheringCatalog.find(offer.target()).filter(offer::equals).isPresent())throw new IllegalArgumentException("Invalid gathering record");}
 public static GatheringRecord create(UUID id,int colony,UUID owner,BlockPos hut,int worker,UUID workerUuid,UUID discovery,GatheringOffer offer,boolean repeat){return new GatheringRecord(id,0,colony,owner,hut,worker,workerUuid,discovery,offer,offer.ticks(),repeat,State.PREPARING,"Preparing expedition");}
 public boolean active(){return state!=State.COMPLETE;}
 private GatheringRecord next(int time,boolean again,State next,String message){return new GatheringRecord(id,Math.addExact(revision,1),colony,owner,hut,worker,workerUuid,discovery,offer,time,again,next,message);}
 public GatheringRecord tick(){if(state!=State.GATHERING)throw new IllegalStateException("Expedition is not gathering");return new GatheringRecord(id,remaining==1?Math.addExact(revision,1):revision,colony,owner,hut,worker,workerUuid,discovery,offer,remaining-1,repeat,remaining==1?State.RETURNING:State.GATHERING,remaining==1?"Returning gathered resources":"Gathering resources");}
 public GatheringRecord transition(State next,String message){boolean legal=state==State.PREPARING&&next==State.GATHERING||state==State.RETURNING&&next==State.COMPLETE||active()&&state!=State.RECOVERY_REQUIRED&&next==State.RECOVERY_REQUIRED;if(!legal)throw new IllegalStateException("Invalid gathering transition");return next(remaining,next==State.RECOVERY_REQUIRED||next==State.COMPLETE?false:repeat,next,message);}
 public GatheringRecord returning(String message){if(!active()||state==State.RECOVERY_REQUIRED||state==State.PREPARING)throw new IllegalStateException("Cannot recall this expedition");if(state==State.RETURNING&&!repeat&&status.equals(message))return this;return next(remaining,false,State.RETURNING,message);}
 public GatheringRecord message(String message){if(status.equals(message))return this;return next(remaining,repeat,state,message);}
 public CompoundTag save(){var t=new CompoundTag();t.putInt("version",1);t.putUUID("id",id);t.putLong("revision",revision);t.putInt("colony",colony);t.putUUID("owner",owner);t.putLong("hut",hut.asLong());t.putInt("worker",worker);t.putUUID("workerUuid",workerUuid);t.putUUID("discovery",discovery);t.put("offer",offer.save());t.putInt("remaining",remaining);t.putBoolean("repeat",repeat);t.putString("state",state.name());t.putString("status",status);return t;}
 public static GatheringRecord load(CompoundTag t){if(t.getInt("version")!=1||!t.hasUUID("id")||!t.hasUUID("owner")||!t.hasUUID("workerUuid")||!t.hasUUID("discovery")||!t.contains("revision",Tag.TAG_LONG)||!t.contains("hut",Tag.TAG_LONG)||!t.contains("remaining",Tag.TAG_INT)||!t.contains("repeat",Tag.TAG_BYTE))throw new IllegalArgumentException("Invalid gathering schema");return new GatheringRecord(t.getUUID("id"),t.getLong("revision"),t.getInt("colony"),t.getUUID("owner"),BlockPos.of(t.getLong("hut")),t.getInt("worker"),t.getUUID("workerUuid"),t.getUUID("discovery"),GatheringOffer.load(t.getCompound("offer")),t.getInt("remaining"),t.getBoolean("repeat"),State.valueOf(t.getString("state")),t.getString("status"));}
}
